/// column-menu: With DataTable
private struct ColumnMenuExample0: View {
    private struct Domain: Identifiable, Sendable {
        let id: String
        let name: String
        let status: String
        let owner: String
        let expires: String

        func value(_ column: String) -> String {
            switch column {
            case "name": name
            case "status": status
            case "owner": owner
            default: expires
            }
        }
    }

    private static let columns: [(id: String, title: String, isHideable: Bool, isHidden: Bool)] = [
        ("name", "Name", false, false),
        ("status", "Status", true, false),
        ("owner", "Owner", true, true),
        ("expires", "Expires", true, false),
    ]
    private let domains = [
        Domain(id: "1", name: "example.com", status: "Active", owner: "Sam Lee", expires: "1 Feb 2027"),
        Domain(id: "2", name: "example.org", status: "Expiring", owner: "Ana Ruiz", expires: "1 Dec 2026"),
    ]
    @State private var visible = Set(Self.columns.filter { !$0.isHidden }.map(\.id))

    private func shown(_ id: String) -> Binding<Bool> {
        Binding(
            get: { visible.contains(id) },
            set: { isOn in
                if isOn { visible.insert(id) } else { visible.remove(id) }
            }
        )
    }

    var body: some View {
        VStack(alignment: .trailing, spacing: MonarchTokens.Space.space3) {
            Menu {
                Section("Visible columns") {
                    ForEach(Self.columns, id: \.id) { column in
                        Toggle(column.title, isOn: shown(column.id))
                            .disabled(!column.isHideable || (visible.count == 1 && visible.contains(column.id)))
                    }
                }
                Divider()
                Button("Show all columns") { visible = Set(Self.columns.map(\.id)) }
                    .disabled(visible.count == Self.columns.count)
                Button("Reset columns") { visible = Set(Self.columns.filter { !$0.isHidden }.map(\.id)) }
            } label: {
                Label("Columns", systemImage: "tablecells")
            }
            .menuStyle(.button)
            .buttonStyle(.monarch(.secondary, size: .sm))
            .accessibilityValue("\(visible.count) of \(Self.columns.count) shown")
            MonarchDataTable(
                "Domains",
                rows: domains,
                columns: Self.columns.map { column in
                    MonarchDataTableColumn<Domain>(column.title, id: column.id, isHideable: column.isHideable, value: { $0.value(column.id) })
                },
                hiddenColumns: Set(Self.columns.map(\.id)).subtracting(visible),
                layout: .table
            )
        }
    }
}

