/// data-grid: 10,000 editable invoices
private struct DataGridExample0: View {
    struct Invoice: Identifiable, Sendable {
        let id: String
        let number: String
        var customer: String
        var status: String
        var amount: Double
        let due: String
    }

    private static let customers = ["Example Ltd", "Sample Co", "Demo GmbH", "Placeholder Inc"]
    private static let statuses = ["Draft", "Sent", "Paid", "Overdue"]
    @State private var invoices: [Invoice] = (0..<10_000).map { (i: Int) -> Invoice in
        Invoice(
            id: "inv-\(i)",
            number: "INV-" + String(format: "%05d", i + 1),
            customer: Self.customers[i % Self.customers.count],
            status: Self.statuses[i % Self.statuses.count],
            amount: Double((i * 7919) % 50_000) / 100,
            due: String(format: "2026-%02d-%02d", i % 12 + 1, i % 27 + 1)
        )
    }
    @State private var sort: MonarchDataTableSort?
    @State private var selection: Set<String> = []

    private func update(_ id: String, _ change: (inout Invoice) -> Void) {
        guard let index = invoices.firstIndex(where: { $0.id == id }) else { return }
        change(&invoices[index])
    }

    var body: some View {
        MonarchDataGrid(
            "Invoices",
            rows: invoices,
            columns: [
                MonarchDataGridColumn("Invoice", id: "number", isHideable: false, pinned: .start, width: 140, value: { $0.number }),
                MonarchDataGridColumn(
                    "Customer",
                    id: "customer",
                    width: 200,
                    edit: MonarchDataGridEdit(
                        isRequired: true,
                        value: { .text($0.customer) },
                        onCommit: { invoice, value in
                            guard case .text(let text) = value else { return }
                            update(invoice.id) { $0.customer = text }
                        }
                    ),
                    value: { $0.customer }
                ),
                MonarchDataGridColumn(
                    "Status",
                    id: "status",
                    width: 140,
                    edit: MonarchDataGridEdit(
                        kind: .select,
                        options: Self.statuses.map { MonarchEditableCellOption($0, value: $0) },
                        value: { .text($0.status) },
                        onCommit: { invoice, value in
                            guard case .text(let text) = value else { return }
                            update(invoice.id) { $0.status = text }
                        }
                    ),
                    value: { $0.status }
                ),
                MonarchDataGridColumn(
                    "Amount",
                    id: "amount",
                    isNumeric: true,
                    width: 130,
                    edit: MonarchDataGridEdit(
                        kind: .number,
                        minimum: 0,
                        value: { .number($0.amount) },
                        onCommit: { invoice, value in
                            guard case .number(let amount) = value else { return }
                            update(invoice.id) { $0.amount = amount }
                        }
                    ),
                    value: { String(format: "%.2f", $0.amount) }
                ),
                MonarchDataGridColumn("Due", id: "due", width: 150, value: { $0.due }),
            ],
            sort: $sort,
            selection: $selection,
            layout: .table,
            rowActions: { invoice in
                [
                    MonarchDataTableRowAction("Open") {},
                    MonarchDataTableRowAction("Delete", isDestructive: true) {
                        invoices.removeAll { $0.id == invoice.id }
                    },
                ]
            }
        )
        .frame(height: 900)
    }
}

